pirate_flagship_bastion.source:
export const envelope = [46, 28, 22];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;

  // Safe block writer confined strictly to envelope
  function setBlock(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      api.set(x, y, z, block);
    }
  }

  function groundAt(x, z) {
    return Math.floor(api.heightAt(x, z));
  }

  // Theme-derived materials
  const woodPlanks = api.theme.wood.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood.log || "minecraft:spruce_log";
  const woodStripped = api.theme.wood.stripped || "minecraft:stripped_spruce_log";
  const woodStairs = api.theme.wood.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme.wood.slab || "minecraft:spruce_slab";
  const woodFence = api.theme.wood.fence || "minecraft:spruce_fence";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:spruce_trapdoor";
  const woodDoor = api.theme.wood.door || "minecraft:spruce_door";

  const stonePrimary = api.theme.stone.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme.stone.accent || "minecraft:cracked_stone_bricks";
  const stoneStairs = api.theme.stone.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme.stone.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme.stone.wall || "minecraft:stone_brick_wall";

  const groundPlinth = api.theme.ground.plinth || "minecraft:smooth_stone";
  const groundRev = api.theme.ground.revetment || "minecraft:cobblestone";

  const roofSolid = api.theme.roof.solid || "minecraft:dark_oak_planks";
  const roofStairs = api.theme.roof.stairs || "minecraft:dark_oak_stairs";
  const roofSlab = api.theme.roof.slab || "minecraft:dark_oak_slab";

  // Specialized ironclad fortress props
  const ironBlock = "minecraft:iron_block";
  const ironBars = "minecraft:iron_bars";
  const chainY = "minecraft:chain[axis=y]";
  const chainX = "minecraft:chain[axis=x]";
  const chainZ = "minecraft:chain[axis=z]";
  const lanternHang = "minecraft:lantern[hanging=true]";
  const lanternFloor = "minecraft:lantern[hanging=false]";
  const barrelUp = "minecraft:barrel[facing=up]";
  const barrelNorth = "minecraft:barrel[facing=north]";
  const dispenserNorth = "minecraft:dispenser[facing=north]";
  const anvilNorth = "minecraft:anvil[facing=north]";
  const anvilEast = "minecraft:anvil[facing=east]";
  const campfireLit = "minecraft:campfire[lit=true]";
  const blastFurnaceNorth = "minecraft:blast_furnace[facing=north]";
  const blackWool = "minecraft:black_wool";
  const redWool = "minecraft:red_wool";

  function withState(blockStr, state) {
    if (!blockStr) return `minecraft:stone[${state}]`;
    if (blockStr.includes("[")) {
      const base = blockStr.split("[")[0];
      return `${base}[${state}]`;
    }
    return `${blockStr}[${state}]`;
  }

  const cz = 11; // Centerline in Z

  // Parametric Galleon Hull Outer Half-Width
  function getHullOuterHalfWidth(x, y) {
    if (x < 2 || x > 44) return -1;

    let maxHeight = 10;
    if (x >= 4 && x <= 13) maxHeight = 13; // Forecastle
    else if (x >= 33 && x <= 43) maxHeight = 18; // Sterncastle
    else if (x >= 14 && x <= 32) maxHeight = 11; // Waist bulwarks
    else if (x >= 2 && x <= 3) maxHeight = 9; // Prow
    else if (x >= 44) maxHeight = 15; // Stern transom

    if (y < 1 || y > maxHeight) return -1;

    let xFactor = 1.0;
    if (x < 18) {
      const t = (x - 2) / 16;
      xFactor = Math.sin(t * Math.PI / 2);
      xFactor = Math.max(0.12, xFactor);
    } else if (x > 32) {
      const t = (x - 32) / 12;
      xFactor = 1.0 - 0.22 * Math.min(1.0, t);
    }

    let yWidth = 0;
    if (y === 1) {
      yWidth = 1.6;
    } else if (y <= 4) {
      yWidth = 1.6 + ((y - 1) / 3) * 4.6; // 1.6 -> 6.2
    } else if (y <= 8) {
      const t = (y - 4) / 4;
      yWidth = 6.2 + 0.4 * Math.sin(t * Math.PI); // up to 6.6
    } else if (y <= 12) {
      const t = (y - 8) / 4;
      yWidth = 6.2 - 0.7 * t; // Tumblehome inwards
    } else {
      if (x >= 33) {
        yWidth = 5.6 - 0.12 * (y - 12);
      } else if (x <= 13) {
        yWidth = 5.2 - 0.18 * (y - 12);
      } else {
        yWidth = 5.4;
      }
    }

    return xFactor * yWidth;
  }

  // 1. TERRAIN FOUNDATION & SHORING SKIRT
  for (let x = 1; x <= 45; x++) {
    for (let z = 1; z <= 21; z++) {
      const hw = getHullOuterHalfWidth(x, 2);
      const isUnderHull = (hw >= 0 && Math.abs(z - cz) <= hw + 0.5);
      const isShoringNorth = (z >= 2 && z <= 5 && (x === 8 || x === 16 || x === 24 || x === 32 || x === 40));
      const isShoringSouth = (z >= 17 && z <= 20 && (x === 8 || x === 16 || x === 32 || x === 40));
      const isRamp = (x >= 20 && x <= 26 && z >= 16 && z <= 21);

      if (isUnderHull || isShoringNorth || isShoringSouth || isRamp) {
        const h = groundAt(x, z);
        const yBottom = Math.max(0, Math.min(2, h));
        for (let y = yBottom; y <= 2; y++) {
          const mat = (y === 0) ? groundPlinth : ((y === 1) ? groundRev : stonePrimary);
          setBlock(x, y, z, mat);
        }
      }
    }
  }

  // 2. KEEL & SKELETON
  for (let x = 1; x <= 44; x++) {
    setBlock(x, 1, cz, withState(woodLog, "axis=x"));
    setBlock(x, 2, cz, withState(woodLog, "axis=x"));
    setBlock(x, 1, cz - 1, groundRev);
    setBlock(x, 1, cz + 1, groundRev);
  }

  // 3. HULL PLATING & IRON ARMOR BANDS
  for (let x = 2; x <= 44; x++) {
    const isRibX = (x % 3 === 1) || (x === 44);

    for (let y = 1; y <= 18; y++) {
      const hw = getHullOuterHalfWidth(x, y);
      if (hw < 0) continue;

      const zMin = Math.round(cz - hw);
      const zMax = Math.round(cz + hw);

      for (let z = zMin; z <= zMax; z++) {
        const isHullWall = (z === zMin || z === zMax || x === 2 || x === 44);

        if (isHullWall) {
          // Determine hull material: Iron plating on combat waterline & North facing
          let mat = woodPlanks;
          if (isRibX) {
            mat = withState(woodLog, "axis=y");
          }

          // Heavy Iron Armor Belt on Y=5..7 (especially North broadside)
          if (y >= 5 && y <= 7) {
            if (z === zMin) {
              // North face combat armor
              mat = (x % 2 === 0) ? ironBlock : stoneAccent;
            } else if (z === zMax) {
              mat = (x % 3 === 0) ? ironBlock : woodStripped;
            } else {
              mat = ironBlock;
            }
          } else if (y === 8 && z === zMin && x % 2 === 1) {
            mat = ironBlock;
          } else if (y <= 3) {
            mat = woodStripped;
          }

          // Top rail capping
          if ((y === 11 && x >= 14 && x <= 32) || (y === 13 && x <= 13) || (y === 18 && x >= 33)) {
            mat = isRibX ? stoneWall : woodPlanks;
          }

          setBlock(x, y, z, mat);
        }
      }
    }
  }

  // 4. DECK FLOORS (Keeping interior rooms hollow for fit-out)
  function layDeck(x1, x2, deckY, material) {
    for (let x = x1; x <= x2; x++) {
      const hw = getHullOuterHalfWidth(x, deckY);
      if (hw < 0) continue;
      const zMin = Math.round(cz - hw) + 1;
      const zMax = Math.round(cz + hw) - 1;
      for (let z = zMin; z <= zMax; z++) {
        setBlock(x, deckY, z, material);
      }
    }
  }

  // Hold floor (Y=2), Lower gun deck (Y=6), Upper gun deck (Y=10)
  layDeck(10, 38, 2, woodPlanks);
  layDeck(5, 42, 6, woodPlanks);
  layDeck(14, 32, 10, woodPlanks); // Waist Main Deck
  layDeck(4, 13, 12, woodPlanks);  // Forecastle Deck
  layDeck(33, 43, 13, woodPlanks); // Quarterdeck
  layDeck(36, 43, 16, woodPlanks); // Poop Deck
  layDeck(36, 42, 19, roofSolid);  // Poop Cabin Roof

  // 5. INTERNAL BULKHEADS & ACCESS OPENINGS
  const bulkheads = [13, 33];
  for (const bx of bulkheads) {
    for (let y = 3; y <= 12; y++) {
      const hw = getHullOuterHalfWidth(bx, y);
      if (hw < 0) continue;
      const zMin = Math.round(cz - hw) + 1;
      const zMax = Math.round(cz + hw) - 1;
      for (let z = zMin; z <= zMax; z++) {
        // Doorway opening in the center
        if ((z === cz || z === cz + 1) && (y === 3 || y === 4 || y === 7 || y === 8 || y === 11)) {
          setBlock(bx, y, z, "minecraft:air");
        } else {
          setBlock(bx, y, z, withState(woodLog, "axis=y"));
        }
      }
    }
  }

  // Internal stairwells between decks
  for (let dy = 3; dy <= 5; dy++) {
    setBlock(20, dy, cz, "minecraft:air");
    setBlock(21, dy, cz, withState(woodStairs, "facing=east,half=bottom"));
  }
  for (let dy = 7; dy <= 9; dy++) {
    setBlock(20, dy, cz, "minecraft:air");
    setBlock(21, dy, cz, withState(woodStairs, "facing=east,half=bottom"));
  }

  // Weather deck stairs to Forecastle and Quarterdeck
  for (let z = cz - 1; z <= cz + 1; z++) {
    setBlock(14, 10, z, withState(woodStairs, "facing=east,half=bottom"));
    setBlock(13, 11, z, withState(woodStairs, "facing=east,half=bottom"));

    setBlock(32, 10, z, withState(woodStairs, "facing=west,half=bottom"));
    setBlock(33, 11, z, withState(woodStairs, "facing=west,half=bottom"));
    setBlock(33, 12, z, withState(woodStairs, "facing=west,half=bottom"));

    setBlock(36, 14, z, withState(woodStairs, "facing=west,half=bottom"));
    setBlock(36, 15, z, withState(woodStairs, "facing=west,half=bottom"));
  }

  // 6. TIERS OF HEAVY CANNONS (POINTING NORTH TOWARD THE UNICORN SANCTUARY)

  // TIER 1: Lower Main Battery (Y=7, Firing Ports at Y=7..8 along North hull)
  const lowerBatteryX = [16, 20, 24, 28, 32];
  for (const bx of lowerBatteryX) {
    const hw = getHullOuterHalfWidth(bx, 7);
    const zGun = Math.round(cz - hw);

    // Gun port opening & reinforced mantlet
    setBlock(bx, 7, zGun, dispenserNorth);
    setBlock(bx, 8, zGun, withState(woodTrapdoor, "facing=north,half=top,open=true"));
    setBlock(bx - 1, 7, zGun, ironBlock);
    setBlock(bx + 1, 7, zGun, ironBlock);

    // Cannon Barrel poking North across the strait
    setBlock(bx, 7, zGun - 1, anvilNorth);

    // Cannon Carriage & Gun Crew Gear inside
    setBlock(bx, 7, zGun + 1, ironBlock);
    setBlock(bx, 7, zGun + 2, stoneAccent);
    setBlock(bx + 1, 7, zGun + 1, barrelUp);
  }

  // TIER 2: Upper Gun Deck Battery (Y=10, Firing Ports at Y=10..11 along North hull)
  const upperBatteryX = [15, 18, 22, 26, 30];
  for (const bx of upperBatteryX) {
    const hw = getHullOuterHalfWidth(bx, 10);
    const zGun = Math.round(cz - hw);

    setBlock(bx, 10, zGun, dispenserNorth);
    setBlock(bx, 10, zGun - 1, anvilNorth);
    setBlock(bx, 11, zGun, ironBars);
    setBlock(bx, 10, zGun + 1, stonePrimary);
    setBlock(bx - 1, 10, zGun + 1, barrelUp);
  }

  // TIER 3: Forecastle Forward Chasers & Heavy Siege Bombard (Y=12..13)
  // Forward Chase Cannon pointing North-West
  const fcNorthZ = Math.round(cz - getHullOuterHalfWidth(6, 13));
  setBlock(6, 13, fcNorthZ, dispenserNorth);
  setBlock(6, 13, fcNorthZ - 1, anvilNorth);
  setBlock(5, 13, fcNorthZ, ironBlock);

  // Forecastle Long-Range Bombard Mortar
  setBlock(9, 13, cz, blastFurnaceNorth);
  setBlock(9, 14, cz, chainY);
  setBlock(8, 13, cz, stoneAccent);
  setBlock(10, 13, cz, stoneAccent);
  setBlock(9, 13, cz - 1, ironBlock);
  setBlock(9, 13, cz + 1, ironBlock);

  // TIER 4: Sterncastle Battery & Elevated Culverin (Y=14..17)
  const sternNorthZ = Math.round(cz - getHullOuterHalfWidth(38, 14));
  setBlock(35, 14, sternNorthZ, dispenserNorth);
  setBlock(35, 14, sternNorthZ - 1, anvilNorth);
  setBlock(39, 14, sternNorthZ, dispenserNorth);
  setBlock(39, 14, sternNorthZ - 1, anvilNorth);

  // Poop Deck High Sniper Gun (Y=17)
  const poopNorthZ = Math.round(cz - getHullOuterHalfWidth(40, 17));
  setBlock(40, 17, poopNorthZ, dispenserNorth);
  setBlock(40, 17, poopNorthZ - 1, anvilNorth);
  setBlock(40, 18, poopNorthZ, ironBars);

  // 7. PROW, NAVAL RAM, BOWSPRIT & ANCHORS (X=0..4)
  // Massive Iron Naval Ram
  for (let rx = 0; rx <= 2; rx++) {
    for (let ry = 4; ry <= 7; ry++) {
      setBlock(rx, ry, cz, ironBlock);
    }
  }
  setBlock(0, 5, cz, anvilEast);
  setBlock(0, 6, cz, anvilEast);
  setBlock(0, 4, cz, ironBars);
  setBlock(0, 7, cz, ironBars);

  // Spiked Bowsprit Spar
  for (let bx = 0; bx <= 5; bx++) {
    const by = 10 + Math.floor((5 - bx) * 0.4);
    setBlock(bx, by, cz, withState(woodLog, "axis=x"));
  }
  setBlock(0, 11, cz, ironBars);
  setBlock(0, 10, cz, chainY);

  // Port Cathead & Anchor Chain
  setBlock(4, 13, cz - 4, withState(woodLog, "axis=z"));
  setBlock(4, 13, cz - 5, withState(woodLog, "axis=z"));
  for (let y = 3; y <= 12; y++) {
    setBlock(4, y, cz - 5, chainY);
  }
  setBlock(4, 3, cz - 5, anvilNorth);
  setBlock(4, 4, cz - 5, ironBars);

  // 8. STERNCASLE BALCONY, GREAT CABIN WINDOWS & BEACON (X=43..45)
  // Stern Balcony Transom
  for (let z = cz - 3; z <= cz + 3; z++) {
    setBlock(44, 10, z, woodPlanks);
    setBlock(45, 10, z, woodSlab);
    setBlock(45, 11, z, ironBars);

    setBlock(44, 13, z, woodPlanks);
    setBlock(45, 13, z, woodSlab);
    setBlock(45, 14, z, ironBars);

    // Great Cabin stern windows
    setBlock(44, 11, z, ironBars);
    setBlock(44, 12, z, ironBars);
  }
  setBlock(45, 12, cz - 3, lanternHang);
  setBlock(45, 12, cz + 3, lanternHang);
  setBlock(45, 15, cz - 3, lanternHang);
  setBlock(45, 15, cz + 3, lanternHang);

  // Fortress Signal Brazier on Poop Deck
  setBlock(39, 17, cz, stoneWall);
  setBlock(39, 18, cz, campfireLit);
  setBlock(38, 18, cz, stoneWall);
  setBlock(40, 18, cz, stoneWall);
  setBlock(39, 18, cz - 1, stoneWall);
  setBlock(39, 18, cz + 1, stoneWall);

  // 9. FORTIFIED MASTS, CROW'S NESTS, WAR BANNERS & CRANE

  // FORE-MAST (X=9, Z=cz)
  for (let y = 7; y <= 25; y++) {
    setBlock(9, y, cz, withState(woodLog, "axis=y"));
  }
  // Fore-mast Yardarm
  for (let z = cz - 4; z <= cz + 4; z++) {
    setBlock(9, 18, z, withState(woodLog, "axis=z"));
  }
  // Fore Crow's Nest
  for (let x = 8; x <= 10; x++) {
    for (let z = cz - 1; z <= cz + 1; z++) {
      setBlock(x, 21, z, woodPlanks);
      if (x === 8 || x === 10 || z === cz - 1 || z === cz + 1) {
        setBlock(x, 22, z, (z === cz - 1) ? ironBars : woodFence);
      }
    }
  }

  // MAIN-MAST & FORTIFIED FIGHTING PLATFORM (X=23, Z=cz)
  for (let y = 7; y <= 27; y++) {
    setBlock(22, y, cz - 1, withState(woodLog, "axis=y"));
    setBlock(23, y, cz - 1, withState(woodLog, "axis=y"));
    setBlock(22, y, cz, withState(woodLog, "axis=y"));
    setBlock(23, y, cz, withState(woodLog, "axis=y"));
  }
  // Lower Fighting Platform (Y=16)
  for (let x = 20; x <= 25; x++) {
    for (let z = cz - 3; z <= cz + 2; z++) {
      setBlock(x, 16, z, woodPlanks);
      if (x === 20 || x === 25 || z === cz - 3 || z === cz + 2) {
        setBlock(x, 17, z, (z === cz - 3) ? ironBars : stoneWall);
      }
    }
  }
  // Main Yardarm (Y=21)
  for (let z = cz - 5; z <= cz + 4; z++) {
    setBlock(22, 21, z, withState(woodLog, "axis=z"));
    setBlock(23, 21, z, withState(woodLog, "axis=z"));
  }
  // Upper Crow's Nest (Y=24..27)
  for (let x = 21; x <= 24; x++) {
    for (let z = cz - 2; z <= cz + 1; z++) {
      setBlock(x, 24, z, woodPlanks);
      setBlock(x, 27, z, roofSlab);
      if (x === 21 || x === 24 || z === cz - 2 || z === cz + 1) {
        setBlock(x, 25, z, woodFence);
      }
    }
  }
  setBlock(21, 25, cz - 2, lanternFloor);

  // Heavy Ammunition Crane (South side boom)
  for (let step = 0; step <= 5; step++) {
    const cx = 23;
    const cy = 18 + Math.floor(step * 0.2);
    const czCrane = cz + 1 + step;
    setBlock(cx, cy, czCrane, withState(woodLog, "axis=z"));
  }
  // Crane Hoist Chain and Suspended Iron Ammo Cage
  for (let y = 13; y <= 18; y++) {
    setBlock(23, y, cz + 6, chainY);
  }
  setBlock(23, 12, cz + 6, ironBlock);
  setBlock(23, 12, cz + 5, ironBars);
  setBlock(23, 12, cz + 7, ironBars);
  setBlock(23, 13, cz + 6, barrelUp);

  // MIZZEN-MAST & PIRATE WAR FLAG (X=36, Z=cz)
  for (let y = 13; y <= 26; y++) {
    setBlock(36, y, cz, withState(woodLog, "axis=y"));
  }
  for (let z = cz - 3; z <= cz + 3; z++) {
    setBlock(36, 20, z, withState(woodLog, "axis=z"));
  }
  // Mizzen Top (Y=22)
  for (let x = 35; x <= 37; x++) {
    for (let z = cz - 1; z <= cz + 1; z++) {
      setBlock(x, 22, z, woodPlanks);
      if (x === 35 || x === 37 || z === cz - 1 || z === cz + 1) {
        setBlock(x, 23, z, woodFence);
      }
    }
  }
  // Waving Pirate Skull & Crossbones Banner
  for (let y = 24; y <= 26; y++) {
    setBlock(36, y, cz + 1, blackWool);
    setBlock(36, y, cz + 2, (y === 25) ? redWool : blackWool);
    setBlock(36, y, cz + 3, blackWool);
  }

  // 10. SHORING STRUTS & SOUTH BOARDING RAMP

  // Angled Timber Props (A-Frames)
  const propX = [8, 16, 24, 32, 40];
  for (const px of propX) {
    // North Struts
    for (let step = 0; step <= 3; step++) {
      const sy = 2 + step;
      const sz = 2 + step;
      setBlock(px, sy, sz, withState(woodLog, "axis=y"));
      setBlock(px, sy, sz + 1, ironBars);
    }
    // South Struts
    if (px !== 24) { // keep clear for ramp at X=24
      for (let step = 0; step <= 3; step++) {
        const sy = 2 + step;
        const sz = 20 - step;
        setBlock(px, sy, sz, withState(woodLog, "axis=y"));
        setBlock(px, sy, sz - 1, ironBars);
      }
    }
  }

  // South Fortress Boarding Ramp (X=20..26, Z=16..21)
  for (let x = 21; x <= 25; x++) {
    for (let step = 0; step <= 5; step++) {
      const rz = 21 - step;
      const ry = 2 + Math.floor(step * 1.5);

      // Support pilings down to terrain
      const h = groundAt(x, rz);
      for (let y = Math.max(0, h); y < ry; y++) {
        setBlock(x, y, rz, (x === 21 || x === 25) ? withState(woodLog, "axis=y") : stonePrimary);
      }

      setBlock(x, ry, rz, (step % 2 === 0) ? woodPlanks : woodSlab);

      if (x === 21 || x === 25) {
        setBlock(x, ry + 1, rz, woodFence);
      }
    }
  }
  // Boarding gate opening in South waist bulwark
  for (let y = 10; y <= 12; y++) {
    setBlock(22, y, cz + 5, "minecraft:air");
    setBlock(23, y, cz + 5, "minecraft:air");
    setBlock(24, y, cz + 5, "minecraft:air");
  }

  // Supply cargo stacks along the dock ramp
  setBlock(21, 3, 21, barrelUp);
  setBlock(21, 4, 21, barrelUp);
  setBlock(25, 3, 21, ironBlock);
  setBlock(25, 4, 21, barrelUp);

  return {
    name: "pirate_flagship_bastion",
    seatY: 0,
    anchors: {
      front: [23, 10, 0],   // Facing North across the channel toward the unicorn island
      door: [23, 2, 21],    // Shore boarding ramp entry
      deck: [23, 10, cz]    // Main waist deck
    },
    interiors: [
      { min: [17, 3, 9], max: [29, 5, 13], kind: "vault" },      // Lower Hold & Powder Magazine
      { min: [15, 7, 8], max: [31, 9, 14], kind: "quarters" },   // Main Gun Deck Barracks
      { min: [34, 11, 8], max: [41, 14, 14], kind: "hall" },     // Captain's War Room & Great Cabin
      { min: [6, 8, 9], max: [12, 11, 13], kind: "quarters" }    // Forecastle Armory & Watch
    ]
  };
}

celestial_unicorn_colossus.source:
export const envelope = [23, 38, 23];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 11;
  const sy = 4; // seat plane at y = 4 to allow 4 courses of foundation down to heightAt = -4

  // Material Palette (Unicorn Sanctuary / Arcane White Quartz theme)
  const stonePri = api.theme?.stone?.primary || "minecraft:quartz_block";
  const stoneAcc = api.theme?.stone?.accent || "minecraft:smooth_quartz";
  const plinth = api.theme?.ground?.plinth || "minecraft:smooth_stone";
  const wallPillar = api.theme?.wall?.tower || "minecraft:quartz_pillar";

  const PALETTE = {
    QUARTZ: stonePri,
    SMOOTH_Q: stoneAcc,
    CALCITE: "minecraft:calcite",
    PILLAR: wallPillar,
    GOLD: "minecraft:gold_block",
    AMETHYST: "minecraft:amethyst_block",
    LANTERN: "minecraft:sea_lantern",
    PLINTH: plinth,
  };

  // 3D Voxel buffer
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () =>
      Array.from({ length: D }, () => null)
    )
  );

  function setV(x, y, z, block) {
    const rx = Math.round(x);
    const ry = Math.round(y);
    const rz = Math.round(z);
    if (rx >= 0 && rx < W && ry >= 0 && ry < H && rz >= 0 && rz < D && block) {
      grid[rx][ry][rz] = block;
    }
  }

  function fillBox(x0, y0, z0, x1, y1, z1, block) {
    const minX = Math.max(0, Math.min(x0, x1));
    const maxX = Math.min(W - 1, Math.max(x0, x1));
    const minY = Math.max(0, Math.min(y0, y1));
    const maxY = Math.min(H - 1, Math.max(y0, y1));
    const minZ = Math.max(0, Math.min(z0, z1));
    const maxZ = Math.min(D - 1, Math.max(z0, z1));
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          setV(x, y, z, typeof block === "function" ? block(x, y, z) : block);
        }
      }
    }
  }

  function fillCapsule(x1, y1, z1, x2, y2, z2, r1, r2, block) {
    const dist = Math.hypot(x2 - x1, y2 - y1, z2 - z1);
    const steps = Math.max(2, Math.ceil(dist * 3));
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const curX = x1 + (x2 - x1) * t;
      const curY = y1 + (y2 - y1) * t;
      const curZ = z1 + (z2 - z1) * t;
      const r = r1 + (r2 - r1) * t;
      const rCeil = Math.ceil(r);
      for (let dx = -rCeil; dx <= rCeil; dx++) {
        for (let dy = -rCeil; dy <= rCeil; dy++) {
          for (let dz = -rCeil; dz <= rCeil; dz++) {
            if (dx * dx + dy * dy + dz * dz <= r * r) {
              setV(curX + dx, curY + dy, curZ + dz, typeof block === "function" ? block(curX + dx, curY + dy, curZ + dz) : block);
            }
          }
        }
      }
    }
  }

  function fillEllipsoid(ecx, ecy, ecz, rx, ry, rz, block) {
    const minX = Math.floor(ecx - rx), maxX = Math.ceil(ecx + rx);
    const minY = Math.floor(ecy - ry), maxY = Math.ceil(ecy + ry);
    const minZ = Math.floor(ecz - rz), maxZ = Math.ceil(ecz + rz);
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          const nx = (x - ecx) / rx;
          const ny = (y - ecy) / ry;
          const nz = (z - ecz) / rz;
          if (nx * nx + ny * ny + nz * nz <= 1.0) {
            setV(x, y, z, typeof block === "function" ? block(x, y, z) : block);
          }
        }
      }
    }
  }

  const horseMat = (x, y, z) => {
    const n = Math.abs(Math.sin(x * 12.3 + y * 7.1 + z * 5.7));
    return n > 0.65 ? PALETTE.CALCITE : PALETTE.SMOOTH_Q;
  };

  // 1. Arcane Pedestal Dais
  for (let y = sy; y <= sy + 3; y++) {
    const layer = y - sy;
    const maxR = 9.2 - layer * 0.9;
    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dx = x - cx;
        const dz = z - 11;
        const dist = Math.hypot(dx, dz);
        const octDist = Math.max(Math.abs(dx), Math.abs(dz), (Math.abs(dx) + Math.abs(dz)) * 0.72);
        if (octDist <= maxR) {
          if (layer === 3) {
            // Dais surface runes & magical ward ring
            if (dist >= 4.8 && dist <= 5.8) {
              grid[x][y][z] = PALETTE.AMETHYST;
            } else if (dist >= 2.0 && dist <= 2.8) {
              grid[x][y][z] = (Math.abs(dx) === Math.abs(dz) || dx === 0 || dz === 0) ? PALETTE.LANTERN : PALETTE.SMOOTH_Q;
            } else if (octDist >= maxR - 0.6) {
              grid[x][y][z] = PALETTE.GOLD;
            } else {
              grid[x][y][z] = (x + z) % 2 === 0 ? PALETTE.SMOOTH_Q : PALETTE.QUARTZ;
            }
          } else if (octDist >= maxR - 0.7) {
            grid[x][y][z] = PALETTE.PILLAR;
          } else {
            grid[x][y][z] = PALETTE.QUARTZ;
          }
        }
      }
    }
  }

  // 2. Foundation Conformation (Rule 6)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (grid[x][sy][z] !== null) {
        const h = api.heightAt(x, z);
        const groundY = Math.max(0, sy + h);
        for (let y = groundY; y < sy; y++) {
          grid[x][y][z] = PALETTE.PLINTH;
        }
        const riseY = Math.min(sy + 3, sy + h);
        for (let y = sy; y <= riseY; y++) {
          if (grid[x][y][z] === null) {
            grid[x][y][z] = PALETTE.PLINTH;
          }
        }
      }
    }
  }

  // 3. Four Diagonal Warding Pylons with Resonant Crystals
  const pylons = [
    [5, 5], [17, 5], [5, 17], [17, 17]
  ];
  for (const [px, pz] of pylons) {
    fillBox(px - 1, sy + 1, pz - 1, px + 1, sy + 3, pz + 1, PALETTE.PILLAR);
    for (let y = sy + 4; y <= sy + 7; y++) {
      setV(px, y, pz, PALETTE.PILLAR);
    }
    // Crystal cap
    setV(px, sy + 8, pz, PALETTE.AMETHYST);
    setV(px, sy + 9, pz, PALETTE.LANTERN);
    setV(px + 1, sy + 9, pz, PALETTE.AMETHYST);
    setV(px - 1, sy + 9, pz, PALETTE.AMETHYST);
    setV(px, sy + 9, pz + 1, PALETTE.AMETHYST);
    setV(px, sy + 9, pz - 1, PALETTE.AMETHYST);
    setV(px, sy + 10, pz, PALETTE.AMETHYST);
    setV(px, sy + 11, pz, PALETTE.AMETHYST);
  }

  // 4. Contested-Sea Front Focus Crystals (projecting wards across the waters to North)
  fillCapsule(7, sy + 3, 3, 6, sy + 7, 2, 0.9, 0.4, PALETTE.AMETHYST);
  fillCapsule(15, sy + 3, 3, 16, sy + 7, 2, 0.9, 0.4, PALETTE.AMETHYST);
  fillCapsule(11, sy + 3, 2, 11, sy + 6, 1.2, 0.9, (x, y, z) => (y === sy + 5 ? PALETTE.LANTERN : PALETTE.AMETHYST));

  // 5. Unicorn Hind Legs & Haunches (anchored to dais)
  // Left Hind Leg
  fillBox(8, sy + 3, 14, 9, sy + 4, 15, PALETTE.GOLD);
  fillCapsule(8.5, sy + 4, 14.5, 8.5, sy + 8, 15, 1.1, 1.1, horseMat);
  fillCapsule(8.5, sy + 8, 15, 9, sy + 12, 13.5, 1.2, 1.5, horseMat);
  fillCapsule(9, sy + 12, 13.5, 10, sy + 15, 13, 1.6, 2.0, horseMat);

  // Right Hind Leg
  fillBox(13, sy + 3, 14, 14, sy + 4, 15, PALETTE.GOLD);
  fillCapsule(13.5, sy + 4, 14.5, 13.5, sy + 8, 15, 1.1, 1.1, horseMat);
  fillCapsule(13.5, sy + 8, 15, 13, sy + 12, 13.5, 1.2, 1.5, horseMat);
  fillCapsule(13, sy + 12, 13.5, 12, sy + 15, 13, 1.6, 2.0, horseMat);

  // 6. Flowing Structural Tail (Connects sacrum to dais for 3-point stable support)
  fillCapsule(11, sy + 15, 14.5, 11, sy + 13, 17, 1.2, 1.3, (x, y, z) => (y % 2 === 0 ? PALETTE.CALCITE : PALETTE.SMOOTH_Q));
  fillCapsule(11, sy + 13, 17, 11, sy + 9, 18.5, 1.3, 1.5, (x, y, z) => ((x + y) % 3 === 0 ? PALETTE.AMETHYST : PALETTE.SMOOTH_Q));
  fillCapsule(11, sy + 9, 18.5, 11, sy + 5, 19, 1.5, 1.7, (x, y, z) => ((x + z) % 2 === 0 ? PALETTE.AMETHYST : PALETTE.CALCITE));
  fillCapsule(11, sy + 5, 19, 11, sy + 3, 18.5, 1.8, 2.0, () => PALETTE.SMOOTH_Q);

  // 7. Rearing Muscular Torso & Celestial Heart
  fillCapsule(11, sy + 15, 13, 11, sy + 17, 11, 2.2, 2.4, horseMat);
  fillCapsule(11, sy + 17, 11, 11, sy + 19, 9, 2.4, 2.5, horseMat);
  fillCapsule(11, sy + 19, 9, 11, sy + 21, 7.5, 2.5, 2.3, horseMat);
  // Radiant chest core
  setV(11, sy + 19, 8, PALETTE.LANTERN);
  setV(11, sy + 19, 7.2, PALETTE.AMETHYST);

  // 8. Forelegs (Reared dynamically in striking pose facing North)
  // Left Foreleg
  fillCapsule(8.5, sy + 20, 7.5, 7.5, sy + 22, 6, 1.4, 1.2, horseMat);
  fillCapsule(7.5, sy + 22, 6, 7.5, sy + 24, 4.5, 1.2, 1.0, horseMat);
  fillCapsule(7.5, sy + 24, 4.5, 7.5, sy + 26, 4, 1.0, 0.9, horseMat);
  fillBox(7, sy + 26.5, 3.2, 8, sy + 27.5, 4.2, PALETTE.GOLD);

  // Right Foreleg
  fillCapsule(13.5, sy + 20, 7.5, 14.5, sy + 22, 6, 1.4, 1.2, horseMat);
  fillCapsule(14.5, sy + 22, 6, 14.5, sy + 24, 4.5, 1.2, 1.0, horseMat);
  fillCapsule(14.5, sy + 24, 4.5, 14.5, sy + 26, 4, 1.0, 0.9, horseMat);
  fillBox(14, sy + 26.5, 3.2, 15, sy + 27.5, 4.2, PALETTE.GOLD);

  // 9. Arched Neck, Sleek Equine Head, and Ears
  fillCapsule(11, sy + 21, 7.5, 11, sy + 24, 6, 2.1, 1.8, horseMat);
  fillCapsule(11, sy + 24, 6, 11, sy + 27, 4.5, 1.8, 1.5, horseMat);
  fillEllipsoid(11, sy + 28, 4, 1.4, 1.4, 1.6, horseMat);
  fillCapsule(11, sy + 27.5, 3.5, 11, sy + 26.5, 2.0, 1.1, 0.8, horseMat);

  // Golden Nostrils & Glowing Relic Eyes
  setV(11, sy + 26.5, 1.5, PALETTE.GOLD);
  setV(11, sy + 26.5, 2.0, PALETTE.GOLD);
  setV(9.8, sy + 28.2, 3.5, PALETTE.LANTERN);
  setV(12.2, sy + 28.2, 3.5, PALETTE.LANTERN);

  // Ears
  fillCapsule(9.8, sy + 29.2, 4.5, 9.2, sy + 31, 4.5, 0.6, 0.3, horseMat);
  fillCapsule(12.2, sy + 29.2, 4.5, 12.8, sy + 31, 4.5, 0.6, 0.3, horseMat);

  // 10. Flowing Celestial Mane
  for (let t = 0; t <= 1; t += 0.08) {
    const my = sy + 29 - t * 7;
    const mz = 5.2 + t * 3.6;
    setV(11, my, mz, PALETTE.CALCITE);
    setV(11, my + 0.4, mz + 0.3, PALETTE.AMETHYST);
    if (Math.round(my) % 2 === 0) {
      setV(10.2, my, mz + 0.2, PALETTE.CALCITE);
      setV(11.8, my, mz + 0.2, PALETTE.SMOOTH_Q);
    }
  }

  // 11. The Glowing Celestial Amethyst Horn
  const hornPoints = [
    { x: 11, y: sy + 29.5, z: 2.8, b: PALETTE.GOLD },
    { x: 11, y: sy + 30.3, z: 2.3, b: PALETTE.AMETHYST },
    { x: 11, y: sy + 31.1, z: 1.9, b: PALETTE.AMETHYST },
    { x: 11, y: sy + 31.9, z: 1.4, b: PALETTE.AMETHYST },
    { x: 11, y: sy + 32.7, z: 1.0, b: PALETTE.LANTERN },
    { x: 11, y: sy + 33.5, z: 0.6, b: PALETTE.AMETHYST },
  ];
  for (const p of hornPoints) {
    setV(p.x, p.y, p.z, p.b);
  }

  // 12. Majestic Winged Arcs (Parametric Feathered Wings)
  for (let side = -1; side <= 1; side += 2) {
    const rootX = 11 + side * 1.8;
    const rootY = sy + 20.5;
    const rootZ = 8.5;

    const sparPoints = [];
    for (let i = 0; i <= 10; i++) {
      const u = i / 10;
      const span = u * 8.5;
      const rise = Math.sin(u * Math.PI * 0.75) * 8.5 + u * 1.5;
      const sweep = u * u * 3.5;
      const wx = rootX + side * span;
      const wy = rootY + rise;
      const wz = rootZ + sweep;
      sparPoints.push([wx, wy, wz, u]);
    }

    // Main Wing Spar
    for (let i = 0; i < sparPoints.length - 1; i++) {
      const p1 = sparPoints[i];
      const p2 = sparPoints[i + 1];
      const r = 1.4 * (1 - p1[3] * 0.6);
      fillCapsule(p1[0], p1[1], p1[2], p2[0], p2[1], p2[2], r, r * 0.8, PALETTE.SMOOTH_Q);
    }

    // Layered Feather Strands
    for (let i = 1; i < sparPoints.length; i++) {
      const [wx, wy, wz, u] = sparPoints[i];
      const featherLen = (1 - Math.abs(u - 0.5) * 1.2) * 5.0 + 2.5;
      const tipX = wx + side * 0.5;
      const tipY = wy - featherLen;
      const tipZ = wz + featherLen * 0.45;

      fillCapsule(wx, wy, wz, tipX, tipY, tipZ, 0.9, 0.4, (x, y, z) => {
        if (y < tipY + 1.2) {
          return u > 0.6 ? PALETTE.AMETHYST : PALETTE.GOLD;
        }
        return (x + y) % 3 === 0 ? PALETTE.CALCITE : PALETTE.SMOOTH_Q;
      });

      // Wing Membrane Webbing
      if (i > 1) {
        const prev = sparPoints[i - 1];
        const prevFeatherLen = (1 - Math.abs(prev[3] - 0.5) * 1.2) * 5.0 + 2.5;
        const pTipX = prev[0] + side * 0.5;
        const pTipY = prev[1] - prevFeatherLen;
        const pTipZ = prev[2] + prevFeatherLen * 0.45;

        const midX = (tipX + pTipX) * 0.5;
        const midY = (tipY + pTipY) * 0.5;
        const midZ = (tipZ + pTipZ) * 0.5;
        fillCapsule(wx, wy, wz, midX, midY, midZ, 0.6, 0.4, PALETTE.QUARTZ);
      }
    }
  }

  // Emit solid voxels to the world
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const blk = grid[x][y][z];
        if (blk !== null) {
          api.set(x, y, z, blk);
        }
      }
    }
  }

  return {
    name: "celestial_unicorn_colossus",
    seatY: sy,
    anchors: {
      front: [cx, sy, 0],
      horn: [cx, sy + 33, 1],
      dais: [cx, sy + 3, 11],
    },
  };
}

coastal_cannon_emplacement.source:
export const envelope = [11, 15, 11];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 3;
  const deckY = 4;
  const variant = api.instance.index % 8;

  // World Theme Palette Roles with robust fallbacks
  const stonePrimary = api.theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:cobblestone";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme?.stone?.wall || "minecraft:stone_brick_wall";

  const woodPlanks = api.theme?.wood?.planks || "minecraft:spruce_planks";
  const woodLog = api.theme?.wood?.log || "minecraft:spruce_log";
  const woodStripped = api.theme?.wood?.stripped || "minecraft:stripped_spruce_log";
  const woodFence = api.theme?.wood?.fence || "minecraft:dark_oak_fence";
  const woodSlab = api.theme?.wood?.slab || "minecraft:spruce_slab";
  const woodStairs = api.theme?.wood?.stairs || "minecraft:spruce_stairs";
  const woodTrapdoor = api.theme?.wood?.trapdoor || "minecraft:spruce_trapdoor";

  const groundPlinth = api.theme?.ground?.plinth || stonePrimary;

  function withState(blockStr, stateStr) {
    const base = blockStr.split("[")[0];
    return `${base}[${stateStr}]`;
  }

  function withAxis(blockStr, axis) {
    const base = blockStr.split("[")[0];
    return `${base}[axis=${axis}]`;
  }

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Battery footprint predicates
  function isPlatform(x, z) {
    if (z >= 1 && z <= 7) {
      if (z === 1) return x >= 3 && x <= 7;
      if (z === 2 || z === 3 || z === 6 || z === 7) return x >= 2 && x <= 8;
      if (z === 4 || z === 5) return x >= 1 && x <= 9;
    }
    if (z === 8) return x >= 3 && x <= 7;
    if (z === 9) return x >= 4 && x <= 6;
    return false;
  }

  function isRim(x, z) {
    if (!isPlatform(x, z)) return false;
    if (z === 1) return true;
    if (z === 2 && (x === 2 || x === 3 || x === 7 || x === 8)) return true;
    if ((z === 3 || z === 6 || z === 7) && (x === 2 || x === 8)) return true;
    if ((z === 4 || z === 5) && (x === 1 || x === 9)) return true;
    if (z === 8 && (x === 3 || x === 7)) return true;
    return false;
  }

  // 1. Terrain Conformance & Substructure Foundation
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (isPlatform(x, z)) {
        const rawH = api.heightAt(x, z);
        const terrainY = Math.max(0, Math.min(deckY, Math.round(seatY + rawH)));

        for (let y = terrainY; y < deckY; y++) {
          let block = stonePrimary;
          const isCorner = (x <= 2 || x >= 8) && (z <= 3 || z >= 6);

          if (isCorner && y >= terrainY + 1) {
            block = withAxis(woodLog, "y");
          } else if (y === terrainY) {
            block = groundPlinth;
          } else if ((x + y + z + variant) % 3 === 0) {
            block = stoneAccent;
          } else if ((x * 2 + z + y) % 5 === 0) {
            block = "minecraft:mossy_cobblestone";
          }
          set(x, y, z, block);
        }

        // Retaining wall if hill rises above platform at rear
        if (seatY + rawH > deckY) {
          const topY = Math.min(H - 1, Math.round(seatY + rawH) + 1);
          for (let y = deckY; y <= topY; y++) {
            if (isRim(x, z) || z >= 7) {
              set(x, y, z, stonePrimary);
            }
          }
        }
      }
    }
  }

  // 2. Battery Platform Deck
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (isPlatform(x, z)) {
        if (z === 9) {
          // Bottom access step at rear
          set(x, deckY - 2, z, withState(woodStairs, "facing=north,half=bottom"));
          set(x, deckY - 3, z, stonePrimary);
        } else if (z === 8 && x >= 4 && x <= 6) {
          // Top access step
          set(x, deckY - 1, z, withState(woodStairs, "facing=north,half=bottom"));
          set(x, deckY - 2, z, stonePrimary);
        } else if (isRim(x, z)) {
          // Stone coping under parapet walls
          set(x, deckY, z, stonePrimary);
        } else {
          // Wooden artillery firing deck
          let deckBlock = woodPlanks;
          if ((x === 4 || x === 5 || x === 6) && z >= 3 && z <= 6) {
            deckBlock = "minecraft:dark_oak_planks";
          } else if ((x + z + variant) % 4 === 0) {
            deckBlock = woodStripped;
          }
          set(x, deckY, z, deckBlock);
        }
      }
    }
  }

  // 3. Fortified Seawall Parapets & Embrasures
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (isRim(x, z)) {
        const isCornerPost = (x === 2 && z === 2) || (x === 8 && z === 2) ||
                             (x === 1 && (z === 4 || z === 5)) || (x === 9 && (z === 4 || z === 5)) ||
                             (x === 2 && z === 7) || (x === 8 && z === 7);

        if (isCornerPost) {
          set(x, 5, z, withAxis(woodLog, "y"));
          set(x, 6, z, withAxis(woodLog, "y"));
          set(x, 7, z, woodFence);
          if ((x + z + variant) % 2 === 0) {
            set(x, 8, z, "minecraft:lantern[hanging=false]");
          }
        } else if (z === 1) {
          if (x === 5) {
            // Main embrasure port
            set(5, 5, 1, withState(stoneSlab, "type=bottom"));
          } else {
            set(x, 5, 1, stonePrimary);
            set(x, 6, 1, stoneWall);
          }
        } else if (z === 2 && (x === 4 || x === 6)) {
          // Flared embrasure cheeks
          if (x === 4) set(4, 5, 2, withState(stoneStairs, "facing=east,half=bottom"));
          if (x === 6) set(6, 5, 2, withState(stoneStairs, "facing=west,half=bottom"));
        } else {
          set(x, 5, z, stonePrimary);
          if ((x + z) % 2 === 0) {
            set(x, 6, z, stoneWall);
          } else {
            set(x, 6, z, stonePrimary);
            set(x, 7, z, withState(stoneSlab, "type=bottom"));
          }
        }
      }
    }
  }

  // Rear entrance balustrades
  set(3, 5, 8, stonePrimary);
  set(3, 6, 8, stoneWall);
  set(7, 5, 8, stonePrimary);
  set(7, 6, 8, stoneWall);

  // 4. Heavy Naval Cannons (Instance Variations)
  if (variant === 0) {
    // Siege Culverin
    set(4, 4, 4, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
    set(6, 4, 4, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
    set(4, 4, 5, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
    set(6, 4, 5, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
    set(5, 4, 4, "minecraft:stripped_dark_oak_log[axis=z]");
    set(5, 4, 5, "minecraft:stripped_dark_oak_log[axis=z]");

    set(5, 5, 7, "minecraft:lever[face=floor,facing=north]");
    set(5, 5, 6, "minecraft:anvil[facing=north]");
    set(5, 5, 5, "minecraft:iron_block");
    set(4, 5, 4, "minecraft:chain[axis=x]");
    set(6, 5, 4, "minecraft:chain[axis=x]");
    set(5, 5, 4, "minecraft:polished_blackstone");
    set(5, 5, 3, "minecraft:cauldron");
    set(5, 5, 2, "minecraft:dispenser[facing=north]");
    set(5, 5, 1, "minecraft:hopper[facing=north]");

    set(3, 5, 5, "minecraft:chain[axis=x]");
    set(2, 5, 5, "minecraft:chain[axis=x]");
    set(7, 5, 5, "minecraft:chain[axis=x]");
    set(8, 5, 5, "minecraft:chain[axis=x]");
  } else if (variant === 1) {
    // NW Swivel Battery
    set(5, 4, 5, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
    set(4, 4, 4, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
    set(6, 4, 6, "minecraft:dark_oak_stairs[facing=south,half=bottom]");

    set(6, 5, 6, "minecraft:anvil[facing=north]");
    set(5, 5, 5, "minecraft:iron_block");
    set(4, 5, 4, "minecraft:polished_blackstone");
    set(4, 5, 3, "minecraft:dispenser[facing=north]");
    set(4, 5, 2, "minecraft:hopper[facing=north]");
    set(5, 6, 5, "minecraft:lever[face=floor,facing=north]");
    set(7, 5, 6, "minecraft:chain[axis=x]");
  } else if (variant === 2) {
    // NE Swivel Battery
    set(5, 4, 5, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
    set(6, 4, 4, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
    set(4, 4, 6, "minecraft:dark_oak_stairs[facing=south,half=bottom]");

    set(4, 5, 6, "minecraft:anvil[facing=north]");
    set(5, 5, 5, "minecraft:iron_block");
    set(6, 5, 4, "minecraft:polished_blackstone");
    set(6, 5, 3, "minecraft:dispenser[facing=north]");
    set(6, 5, 2, "minecraft:hopper[facing=north]");
    set(5, 6, 5, "minecraft:lever[face=floor,facing=north]");
    set(3, 5, 6, "minecraft:chain[axis=x]");
  } else if (variant === 3) {
    // Twin Broadsiders
    set(4, 4, 4, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
    set(4, 4, 5, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
    set(4, 5, 6, "minecraft:polished_blackstone");
    set(4, 5, 5, "minecraft:iron_block");
    set(4, 5, 4, "minecraft:polished_blackstone");
    set(4, 5, 3, "minecraft:dispenser[facing=north]");
    set(4, 5, 2, "minecraft:hopper[facing=north]");
    set(4, 6, 6, "minecraft:lever[face=floor,facing=north]");

    set(6, 4, 4, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
    set(6, 4, 5, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
    set(6, 5, 6, "minecraft:polished_blackstone");
    set(6, 5, 5, "minecraft:iron_block");
    set(6, 5, 4, "minecraft:polished_blackstone");
    set(6, 5, 3, "minecraft:dispenser[facing=north]");
    set(6, 5, 2, "minecraft:hopper[facing=north]");
    set(6, 6, 6, "minecraft:lever[face=floor,facing=north]");

    set(5, 5, 5, "minecraft:barrel[facing=up]");
    set(5, 6, 5, "minecraft:lantern[hanging=false]");
  } else if (variant === 4) {
    // High-Angle Coastal Mortar
    set(4, 4, 4, "minecraft:polished_blackstone_slab[type=bottom]");
    set(5, 4, 4, "minecraft:polished_blackstone_slab[type=bottom]");
    set(6, 4, 4, "minecraft:polished_blackstone_slab[type=bottom]");
    set(4, 4, 5, "minecraft:polished_blackstone_slab[type=bottom]");
    set(5, 4, 5, "minecraft:polished_blackstone_slab[type=bottom]");
    set(6, 4, 5, "minecraft:polished_blackstone_slab[type=bottom]");

    set(5, 5, 5, "minecraft:anvil[facing=north]");
    set(4, 5, 4, "minecraft:grindstone[facing=north]");
    set(6, 5, 4, "minecraft:grindstone[facing=north]");
    set(5, 5, 4, "minecraft:iron_block");
    set(5, 6, 4, "minecraft:dispenser[facing=up]");
    set(5, 6, 3, "minecraft:polished_blackstone_stairs[facing=north,half=top]");
    set(5, 5, 3, "minecraft:cauldron");
  } else if (variant === 5) {
    // Armored Drake with Gun Shield
    set(4, 4, 4, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
    set(6, 4, 4, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
    set(4, 4, 5, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
    set(6, 4, 5, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
    set(5, 4, 4, "minecraft:stripped_dark_oak_log[axis=z]");
    set(5, 4, 5, "minecraft:stripped_dark_oak_log[axis=z]");

    set(5, 5, 6, "minecraft:anvil[facing=north]");
    set(5, 5, 5, "minecraft:iron_block");
    set(5, 5, 4, "minecraft:polished_blackstone");
    set(5, 5, 3, "minecraft:dispenser[facing=north]");
    set(5, 5, 2, "minecraft:hopper[facing=north]");

    set(4, 6, 2, "minecraft:dark_oak_trapdoor[facing=south,half=bottom,open=false]");
    set(5, 6, 2, "minecraft:dark_oak_trapdoor[facing=south,half=bottom,open=false]");
    set(6, 6, 2, "minecraft:dark_oak_trapdoor[facing=south,half=bottom,open=false]");
    set(4, 7, 2, "minecraft:dark_oak_fence");
    set(6, 7, 2, "minecraft:dark_oak_fence");
  } else if (variant === 6) {
    // Cursed Soul Battery
    set(4, 4, 4, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
    set(6, 4, 4, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
    set(4, 4, 5, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
    set(6, 4, 5, "minecraft:dark_oak_stairs[facing=north,half=bottom]");

    set(5, 5, 6, "minecraft:anvil[facing=north]");
    set(5, 5, 5, "minecraft:polished_blackstone");
    set(5, 5, 4, "minecraft:iron_block");
    set(5, 5, 3, "minecraft:dispenser[facing=north]");
    set(5, 5, 2, "minecraft:hopper[facing=north]");

    set(3, 5, 3, "minecraft:cauldron");
    set(7, 5, 3, "minecraft:soul_campfire[lit=true]");
    set(5, 6, 6, "minecraft:redstone_wire");
  } else {
    // Long 32-Pounder Shore Gun
    set(4, 4, 4, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
    set(6, 4, 4, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
    set(4, 4, 5, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
    set(6, 4, 5, "minecraft:dark_oak_stairs[facing=north,half=bottom]");

    set(5, 5, 7, "minecraft:anvil[facing=north]");
    set(5, 5, 6, "minecraft:iron_block");
    set(5, 5, 5, "minecraft:polished_blackstone");
    set(5, 5, 4, "minecraft:polished_blackstone");
    set(5, 5, 3, "minecraft:cauldron");
    set(5, 5, 2, "minecraft:dispenser[facing=north]");

    set(3, 5, 4, "minecraft:cauldron");
    set(3, 6, 4, woodFence);
  }

  // 5. Powder Magazine, TNT Kegs & Munitions
  if (variant === 0 || variant === 4 || variant === 6) {
    set(2, 5, 6, "minecraft:barrel[facing=up]");
    set(2, 5, 7, "minecraft:tnt");
    set(2, 6, 7, "minecraft:dark_oak_trapdoor[half=bottom]");
    set(3, 5, 7, "minecraft:barrel[facing=east]");
    set(2, 6, 6, "minecraft:barrel[facing=up]");

    set(7, 5, 6, "minecraft:chest[facing=north]");
    set(7, 5, 5, "minecraft:wither_skeleton_skull[rotation=0]");
    set(8, 5, 5, "minecraft:wither_skeleton_skull[rotation=4]");
    set(7, 5, 4, "minecraft:wither_skeleton_skull[rotation=8]");
  } else if (variant === 1 || variant === 5) {
    set(8, 5, 6, "minecraft:barrel[facing=up]");
    set(8, 5, 7, "minecraft:barrel[facing=north]");
    set(7, 5, 7, "minecraft:tnt");
    set(7, 6, 7, "minecraft:dark_oak_trapdoor[half=bottom]");
    set(8, 6, 6, "minecraft:barrel[facing=up]");

    set(3, 5, 6, "minecraft:barrel[facing=up]");
    set(3, 5, 5, "minecraft:wither_skeleton_skull[rotation=0]");
    set(2, 5, 5, "minecraft:wither_skeleton_skull[rotation=4]");
    set(3, 5, 4, "minecraft:wither_skeleton_skull[rotation=8]");
  } else {
    set(2, 5, 6, "minecraft:barrel[facing=up]");
    set(2, 5, 7, "minecraft:barrel[facing=north]");
    set(3, 5, 7, "minecraft:tnt");
    set(3, 6, 7, "minecraft:dark_oak_trapdoor[half=bottom]");

    set(7, 5, 6, "minecraft:chest[facing=north]");
    set(8, 5, 6, "minecraft:barrel[facing=up]");
    set(7, 5, 5, "minecraft:wither_skeleton_skull[rotation=0]");
    set(8, 5, 5, "minecraft:wither_skeleton_skull[rotation=4]");
  }

  // 6. Mast & Tattered Jolly Roger Black Flag
  let mastX = 8;
  let mastZ = 7;
  if (variant === 1 || variant === 5) {
    mastX = 2;
    mastZ = 7;
  } else if (variant === 3 || variant === 7) {
    mastX = 5;
    mastZ = 8;
  }

  // Mast Trunk
  set(mastX, 4, mastZ, withAxis(woodLog, "y"));
  set(mastX, 5, mastZ, withAxis(woodLog, "y"));
  set(mastX, 6, mastZ, withAxis(woodLog, "y"));
  set(mastX, 7, mastZ, withAxis(woodLog, "y"));
  set(mastX, 8, mastZ, woodFence);
  set(mastX, 9, mastZ, woodFence);
  set(mastX, 10, mastZ, woodFence);
  set(mastX, 11, mastZ, woodFence);
  set(mastX, 12, mastZ, woodFence);
  set(mastX, 13, mastZ, woodFence);
  set(mastX, 14, mastZ, "minecraft:skeleton_skull[rotation=0]");

  // Yardarm and Tattered Flag
  if (mastX === 8) {
    set(7, 12, 7, woodFence);
    set(6, 12, 7, woodFence);
    set(5, 12, 7, woodFence);

    // Upper Flag Row
    set(7, 11, 7, "minecraft:black_wool");
    set(6, 11, 7, "minecraft:white_wool");
    set(5, 11, 7, "minecraft:black_wool");

    // Middle Flag Row
    set(7, 10, 7, "minecraft:black_wool");
    set(6, 10, 7, "minecraft:black_wool");
    set(5, 10, 7, "minecraft:black_wool");

    // Tattered Streamers
    set(7, 9, 7, "minecraft:black_banner[rotation=0]");
    set(5, 9, 7, "minecraft:black_banner[rotation=0]");
  } else if (mastX === 2) {
    set(3, 12, 7, woodFence);
    set(4, 12, 7, woodFence);
    set(5, 12, 7, woodFence);

    set(3, 11, 7, "minecraft:black_wool");
    set(4, 11, 7, "minecraft:white_wool");
    set(5, 11, 7, "minecraft:black_wool");

    set(3, 10, 7, "minecraft:black_wool");
    set(4, 10, 7, "minecraft:black_wool");
    set(5, 10, 7, "minecraft:black_wool");

    set(3, 9, 7, "minecraft:black_banner[rotation=0]");
    set(5, 9, 7, "minecraft:black_banner[rotation=0]");
  } else {
    // Central Yardarm
    set(4, 12, 8, woodFence);
    set(3, 12, 8, woodFence);
    set(6, 12, 8, woodFence);
    set(7, 12, 8, woodFence);

    set(4, 11, 8, "minecraft:black_wool");
    set(5, 11, 8, "minecraft:white_wool");
    set(6, 11, 8, "minecraft:black_wool");

    set(3, 11, 8, "minecraft:black_wool");
    set(7, 11, 8, "minecraft:black_wool");

    set(4, 10, 8, "minecraft:black_wool");
    set(6, 10, 8, "minecraft:black_wool");

    set(3, 9, 8, "minecraft:black_banner[rotation=0]");
    set(7, 9, 8, "minecraft:black_banner[rotation=0]");
  }

  return {
    name: "coastal_cannon_emplacement",
    seatY: seatY,
    anchors: {
      front: [5, deckY, 0],
      door: [5, deckY - 1, 9]
    }
  };
}

warding_crystal_pylon.source:
export const envelope = [9, 16, 9];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 4;
  const cz = 4;
  const seatY = 4;

  const theme = api.theme || {};
  const stonePrimary = (theme.stone && theme.stone.primary) || "minecraft:smooth_quartz";
  const stonePlinth = (theme.ground && theme.ground.plinth) || "minecraft:quartz_bricks";
  const stonePavement = (theme.ground && theme.ground.pavement) || "minecraft:calcite";
  const stoneStairsRaw = (theme.stone && theme.stone.stairs) || "minecraft:quartz_stairs";
  const stoneSlabRaw = (theme.stone && theme.stone.slab) || "minecraft:quartz_slab";

  // 3D Grid buffer to assemble structure deterministically
  const grid = [];
  for (let x = 0; x < W; x++) {
    grid[x] = [];
    for (let y = 0; y < H; y++) {
      grid[x][y] = [];
      for (let z = 0; z < D; z++) {
        grid[x][y][z] = null;
      }
    }
  }

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  function getStairFacing(x, z, originX, originZ) {
    const ox = originX !== undefined ? originX : cx;
    const oz = originZ !== undefined ? originZ : cz;
    const dx = x - ox;
    const dz = z - oz;
    if (Math.abs(dz) >= Math.abs(dx)) {
      return dz < 0 ? "north" : "south";
    }
    return dx < 0 ? "west" : "east";
  }

  function makeStair(baseName, facing, half) {
    const clean = baseName.split("[")[0];
    const h = half || "bottom";
    return clean + "[facing=" + facing + ",half=" + h + "]";
  }

  function makeSlab(baseName, type) {
    const clean = baseName.split("[")[0];
    const t = type || "bottom";
    return clean + "[type=" + t + "]";
  }

  // Determine plugin style based on instance index
  const instIdx = api.instance ? api.instance.index : 0;
  const styleIdx = ((instIdx % 8) + 8) % 8;

  // -------------------------------------------------------------
  // 1. BASE DAIS & RUNIC PAVEMENT (y = seatY = 4)
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.hypot(dx, dz);

      if (dist <= 3.8) {
        if (dist > 2.8) {
          // Outer border & steps
          if (dist > 3.2) {
            const facing = getStairFacing(x, z);
            setBlock(x, seatY, z, makeStair(stoneStairsRaw, facing, "bottom"));
          } else {
            setBlock(x, seatY, z, stonePlinth);
          }
        } else {
          // Inner runic floor inlay
          let floorBlock = stonePavement;
          const isCardinal = dx === 0 || dz === 0;
          const isDiagonal = Math.abs(dx) === Math.abs(dz);

          if (styleIdx === 0) {
            if (dist < 1.2) floorBlock = "minecraft:sea_lantern";
            else if (isCardinal) floorBlock = "minecraft:crying_obsidian";
            else if (isDiagonal) floorBlock = "minecraft:amethyst_block";
          } else if (styleIdx === 1) {
            if (dist < 1.2) floorBlock = "minecraft:gold_block";
            else if (isCardinal) floorBlock = "minecraft:sea_lantern";
            else if (isDiagonal) floorBlock = "minecraft:quartz_bricks";
          } else if (styleIdx === 2) {
            if (dist < 1.2) floorBlock = "minecraft:budding_amethyst";
            else if ((dx + dz) % 2 === 0) floorBlock = "minecraft:amethyst_block";
            else floorBlock = "minecraft:crying_obsidian";
          } else if (styleIdx === 3) {
            if (isCardinal) floorBlock = "minecraft:sea_lantern";
            else if (dist < 2.0) floorBlock = "minecraft:chiseled_quartz_block";
          } else if (styleIdx === 4) {
            if (isDiagonal || isCardinal) floorBlock = "minecraft:lapis_block";
            else floorBlock = "minecraft:smooth_quartz";
          } else if (styleIdx === 5) {
            if (Math.round(dist) === 2) floorBlock = "minecraft:crying_obsidian";
            else if (dist < 1.5) floorBlock = "minecraft:sea_lantern";
          } else if (styleIdx === 6) {
            if (isDiagonal) floorBlock = "minecraft:amethyst_block";
            else if (isCardinal) floorBlock = "minecraft:calcite";
            else floorBlock = "minecraft:smooth_quartz";
          } else if (styleIdx === 7) {
            if (dz <= 0 && dx === 0) floorBlock = "minecraft:sea_lantern";
            else if (dz > 0 && Math.abs(dx) <= 1) floorBlock = "minecraft:crying_obsidian";
            else floorBlock = "minecraft:gilded_blackstone";
          }

          setBlock(x, seatY, z, floorBlock);
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 2. INNER RAISED PLATFORM (y = seatY + 1 = 5)
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const dist = Math.hypot(dx, dz);

      if (dist <= 2.2) {
        if (dist > 1.5) {
          const facing = getStairFacing(x, z);
          setBlock(x, seatY + 1, z, makeStair("minecraft:quartz_stairs", facing, "bottom"));
        } else {
          setBlock(x, seatY + 1, z, "minecraft:chiseled_quartz_block");
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 3. FOUR CORNER WARDING PEDESTALS / MINI-PYLONS
  // -------------------------------------------------------------
  const cornerOffsets = [
    [-2, -2],
    [2, -2],
    [-2, 2],
    [2, 2],
  ];

  for (let i = 0; i < cornerOffsets.length; i++) {
    const ox = cornerOffsets[i][0];
    const oz = cornerOffsets[i][1];
    const px = cx + ox;
    const pz = cz + oz;

    setBlock(px, seatY + 1, pz, "minecraft:quartz_pillar[axis=y]");
    setBlock(px, seatY + 2, pz, "minecraft:chiseled_quartz_block");

    if (styleIdx === 0 || styleIdx === 6) {
      setBlock(px, seatY + 3, pz, "minecraft:amethyst_cluster[facing=up]");
    } else if (styleIdx === 1 || styleIdx === 4 || styleIdx === 7) {
      setBlock(px, seatY + 3, pz, "minecraft:end_rod[facing=up]");
    } else if (styleIdx === 2) {
      setBlock(px, seatY + 3, pz, "minecraft:large_amethyst_bud[facing=up]");
    } else if (styleIdx === 3) {
      setBlock(px, seatY + 3, pz, "minecraft:sea_lantern");
      setBlock(px, seatY + 4, pz, makeSlab("minecraft:quartz_slab", "bottom"));
    } else {
      setBlock(px, seatY + 3, pz, "minecraft:crying_obsidian");
      setBlock(px, seatY + 4, pz, "minecraft:small_amethyst_bud[facing=up]");
    }
  }

  // -------------------------------------------------------------
  // 4. MAIN WARDING PYLON SHAFT (y = 6 to 11)
  // -------------------------------------------------------------

  // Level 6 (Lower Plinth Tier)
  setBlock(cx, seatY + 2, cz, "minecraft:sea_lantern");
  setBlock(cx + 1, seatY + 2, cz, "minecraft:quartz_pillar[axis=y]");
  setBlock(cx - 1, seatY + 2, cz, "minecraft:quartz_pillar[axis=y]");
  setBlock(cx, seatY + 2, cz + 1, "minecraft:quartz_pillar[axis=y]");
  setBlock(cx, seatY + 2, cz - 1, "minecraft:quartz_pillar[axis=y]");
  setBlock(cx + 1, seatY + 2, cz + 1, makeStair("minecraft:quartz_stairs", "south", "bottom"));
  setBlock(cx - 1, seatY + 2, cz + 1, makeStair("minecraft:quartz_stairs", "south", "bottom"));
  setBlock(cx + 1, seatY + 2, cz - 1, makeStair("minecraft:quartz_stairs", "north", "bottom"));
  setBlock(cx - 1, seatY + 2, cz - 1, makeStair("minecraft:quartz_stairs", "north", "bottom"));

  // Level 7 (Lower Shaft)
  const core7 = styleIdx === 2 ? "minecraft:budding_amethyst" : "minecraft:crying_obsidian";
  setBlock(cx, seatY + 3, cz, core7);
  setBlock(cx + 1, seatY + 3, cz, "minecraft:quartz_pillar[axis=y]");
  setBlock(cx - 1, seatY + 3, cz, "minecraft:quartz_pillar[axis=y]");
  setBlock(cx, seatY + 3, cz + 1, "minecraft:quartz_pillar[axis=y]");
  setBlock(cx, seatY + 3, cz - 1, "minecraft:quartz_pillar[axis=y]");
  setBlock(cx + 1, seatY + 3, cz + 1, makeStair("minecraft:quartz_stairs", "south", "top"));
  setBlock(cx - 1, seatY + 3, cz + 1, makeStair("minecraft:quartz_stairs", "south", "top"));
  setBlock(cx + 1, seatY + 3, cz - 1, makeStair("minecraft:quartz_stairs", "north", "top"));
  setBlock(cx - 1, seatY + 3, cz - 1, makeStair("minecraft:quartz_stairs", "north", "top"));

  // Level 8 (Mid Shaft Transition)
  const core8 = styleIdx === 1 ? "minecraft:gold_block" : "minecraft:sea_lantern";
  setBlock(cx, seatY + 4, cz, core8);
  setBlock(cx + 1, seatY + 4, cz, "minecraft:smooth_quartz");
  setBlock(cx - 1, seatY + 4, cz, "minecraft:smooth_quartz");
  setBlock(cx, seatY + 4, cz + 1, "minecraft:smooth_quartz");
  setBlock(cx, seatY + 4, cz - 1, "minecraft:smooth_quartz");
  setBlock(cx + 1, seatY + 4, cz + 1, makeSlab("minecraft:quartz_slab", "bottom"));
  setBlock(cx - 1, seatY + 4, cz + 1, makeSlab("minecraft:quartz_slab", "bottom"));
  setBlock(cx + 1, seatY + 4, cz - 1, makeSlab("minecraft:quartz_slab", "bottom"));
  setBlock(cx - 1, seatY + 4, cz - 1, makeSlab("minecraft:quartz_slab", "bottom"));

  // Level 9 (High Shaft Body)
  if (styleIdx === 3) {
    setBlock(cx - 1, seatY + 5, cz, "minecraft:quartz_pillar[axis=y]");
    setBlock(cx + 1, seatY + 5, cz, "minecraft:quartz_pillar[axis=y]");
    setBlock(cx, seatY + 5, cz, "minecraft:sea_lantern");
  } else if (styleIdx === 5) {
    setBlock(cx, seatY + 5, cz, "minecraft:sea_lantern");
    setBlock(cx + 1, seatY + 5, cz, "minecraft:tinted_glass");
    setBlock(cx - 1, seatY + 5, cz, "minecraft:tinted_glass");
    setBlock(cx, seatY + 5, cz + 1, "minecraft:tinted_glass");
    setBlock(cx, seatY + 5, cz - 1, "minecraft:tinted_glass");
  } else {
    const cardBlock = styleIdx === 2 ? "minecraft:amethyst_block" : "minecraft:quartz_pillar[axis=y]";
    setBlock(cx, seatY + 5, cz, "minecraft:amethyst_block");
    setBlock(cx + 1, seatY + 5, cz, cardBlock);
    setBlock(cx - 1, seatY + 5, cz, cardBlock);
    setBlock(cx, seatY + 5, cz + 1, cardBlock);
    setBlock(cx, seatY + 5, cz - 1, cardBlock);
  }

  // Level 10 (Neck / Taper)
  if (styleIdx === 3) {
    setBlock(cx - 1, seatY + 6, cz, "minecraft:quartz_pillar[axis=y]");
    setBlock(cx + 1, seatY + 6, cz, "minecraft:quartz_pillar[axis=y]");
    setBlock(cx, seatY + 6, cz, "minecraft:amethyst_block");
  } else {
    setBlock(cx, seatY + 6, cz, "minecraft:smooth_quartz");
    setBlock(cx + 1, seatY + 6, cz, makeStair("minecraft:quartz_stairs", "east", "top"));
    setBlock(cx - 1, seatY + 6, cz, makeStair("minecraft:quartz_stairs", "west", "top"));
    setBlock(cx, seatY + 6, cz + 1, makeStair("minecraft:quartz_stairs", "south", "top"));
    setBlock(cx, seatY + 6, cz - 1, makeStair("minecraft:quartz_stairs", "north", "top"));
  }

  // Level 11 (Spire Base)
  if (styleIdx === 3) {
    setBlock(cx - 1, seatY + 7, cz, makeStair("minecraft:quartz_stairs", "east", "bottom"));
    setBlock(cx + 1, seatY + 7, cz, makeStair("minecraft:quartz_stairs", "west", "bottom"));
    setBlock(cx, seatY + 7, cz, "minecraft:sea_lantern");
  } else {
    const spCore = styleIdx === 0 || styleIdx === 6 ? "minecraft:sea_lantern" : "minecraft:amethyst_block";
    setBlock(cx, seatY + 7, cz, spCore);
  }

  // -------------------------------------------------------------
  // 5. UNIQUE CROWN / FINIAL ARCHETYPES (y = 12 to 15)
  // -------------------------------------------------------------
  if (styleIdx === 0) {
    setBlock(cx, seatY + 8, cz, "minecraft:amethyst_block");
    setBlock(cx + 1, seatY + 8, cz, "minecraft:amethyst_cluster[facing=east]");
    setBlock(cx - 1, seatY + 8, cz, "minecraft:amethyst_cluster[facing=west]");
    setBlock(cx, seatY + 8, cz + 1, "minecraft:amethyst_cluster[facing=south]");
    setBlock(cx, seatY + 8, cz - 1, "minecraft:amethyst_cluster[facing=north]");
    setBlock(cx, seatY + 9, cz, "minecraft:amethyst_block");
    setBlock(cx, seatY + 10, cz, "minecraft:end_rod[facing=up]");
  } else if (styleIdx === 1) {
    setBlock(cx, seatY + 8, cz, "minecraft:sea_lantern");
    setBlock(cx + 1, seatY + 8, cz, makeStair("minecraft:quartz_stairs", "west", "bottom"));
    setBlock(cx - 1, seatY + 8, cz, makeStair("minecraft:quartz_stairs", "east", "bottom"));
    setBlock(cx, seatY + 8, cz + 1, makeStair("minecraft:quartz_stairs", "north", "bottom"));
    setBlock(cx, seatY + 8, cz - 1, makeStair("minecraft:quartz_stairs", "south", "bottom"));
    setBlock(cx, seatY + 9, cz, "minecraft:smooth_quartz");
    setBlock(cx, seatY + 10, cz, makeSlab("minecraft:quartz_slab", "bottom"));
    setBlock(cx, seatY + 11, cz, "minecraft:end_rod[facing=up]");
  } else if (styleIdx === 2) {
    setBlock(cx, seatY + 8, cz, "minecraft:budding_amethyst");
    setBlock(cx + 1, seatY + 8, cz, "minecraft:large_amethyst_bud[facing=east]");
    setBlock(cx - 1, seatY + 8, cz, "minecraft:large_amethyst_bud[facing=west]");
    setBlock(cx, seatY + 8, cz + 1, "minecraft:large_amethyst_bud[facing=south]");
    setBlock(cx, seatY + 8, cz - 1, "minecraft:large_amethyst_bud[facing=north]");
    setBlock(cx, seatY + 9, cz, "minecraft:amethyst_block");
    setBlock(cx, seatY + 10, cz, "minecraft:amethyst_cluster[facing=up]");
  } else if (styleIdx === 3) {
    setBlock(cx, seatY + 8, cz, "minecraft:amethyst_block");
    setBlock(cx, seatY + 9, cz, "minecraft:sea_lantern");
    setBlock(cx, seatY + 10, cz, "minecraft:amethyst_cluster[facing=up]");
  } else if (styleIdx === 4) {
    setBlock(cx, seatY + 8, cz, "minecraft:quartz_pillar[axis=y]");
    setBlock(cx, seatY + 9, cz, "minecraft:smooth_quartz");
    setBlock(cx, seatY + 10, cz, "minecraft:quartz_pillar[axis=y]");
    setBlock(cx, seatY + 11, cz, "minecraft:end_rod[facing=up]");
  } else if (styleIdx === 5) {
    setBlock(cx, seatY + 8, cz, "minecraft:sea_lantern");
    setBlock(cx + 1, seatY + 8, cz, "minecraft:tinted_glass");
    setBlock(cx - 1, seatY + 8, cz, "minecraft:tinted_glass");
    setBlock(cx, seatY + 8, cz + 1, "minecraft:tinted_glass");
    setBlock(cx, seatY + 8, cz - 1, "minecraft:tinted_glass");
    setBlock(cx, seatY + 9, cz, "minecraft:amethyst_block");
    setBlock(cx, seatY + 10, cz, "minecraft:end_rod[facing=up]");
  } else if (styleIdx === 6) {
    setBlock(cx, seatY + 8, cz, "minecraft:sea_lantern");
    setBlock(cx + 1, seatY + 8, cz, makeStair("minecraft:quartz_stairs", "west", "bottom"));
    setBlock(cx - 1, seatY + 8, cz, makeStair("minecraft:quartz_stairs", "east", "bottom"));
    setBlock(cx, seatY + 8, cz + 1, makeStair("minecraft:quartz_stairs", "north", "bottom"));
    setBlock(cx, seatY + 8, cz - 1, makeStair("minecraft:quartz_stairs", "south", "bottom"));
    setBlock(cx, seatY + 9, cz, "minecraft:amethyst_block");
    setBlock(cx, seatY + 10, cz, "minecraft:amethyst_cluster[facing=up]");
  } else if (styleIdx === 7) {
    setBlock(cx, seatY + 8, cz, "minecraft:gilded_blackstone");
    setBlock(cx, seatY + 8, cz - 1, "minecraft:sea_lantern");
    setBlock(cx, seatY + 8, cz + 1, "minecraft:crying_obsidian");
    setBlock(cx, seatY + 9, cz, "minecraft:sea_lantern");
    setBlock(cx, seatY + 9, cz - 1, makeStair("minecraft:quartz_stairs", "north", "bottom"));
    setBlock(cx, seatY + 9, cz - 2, "minecraft:end_rod[facing=north]");
    setBlock(cx, seatY + 10, cz, "minecraft:smooth_quartz");
    setBlock(cx, seatY + 11, cz, "minecraft:end_rod[facing=up]");
  }

  // -------------------------------------------------------------
  // 6. TERRAIN CONFORMANCE (Rule 6: 5 ground profiles)
  // -------------------------------------------------------------
  const occupied = [];
  for (let x = 0; x < W; x++) {
    occupied[x] = [];
    for (let z = 0; z < D; z++) {
      occupied[x][z] = false;
      for (let y = seatY; y < H; y++) {
        if (grid[x][y][z] !== null) {
          occupied[x][z] = true;
          break;
        }
      }
    }
  }

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      if (occupied[x][z]) {
        const h = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(H - 1, seatY + h));

        if (groundY < seatY) {
          for (let y = groundY; y < seatY; y++) {
            if (grid[x][y][z] === null) {
              grid[x][y][z] = y === groundY ? stonePlinth : stonePrimary;
            }
          }
        } else if (groundY > seatY) {
          for (let y = seatY; y <= groundY; y++) {
            if (grid[x][y][z] === null) {
              grid[x][y][z] = stonePrimary;
            }
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 7. EMIT BLOCKS TO WORLD
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const b = grid[x][y][z];
        if (b !== null) {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "warding_crystal_pylon",
    seatY: seatY,
    anchors: {
      front: [cx, seatY, 0],
    },
  };
}
